fun rmsOf(block: ByteArray): Float {
    val sampleCount = block.size / 2
    if (sampleCount == 0) return 0f
    var sum = 0.0
    for (i in 0 until sampleCount) {
        val s = ((block[2 * i + 1].toInt() shl 8) or (block[2 * i].toInt() and 0xFF)).toShort().toInt()
        sum += s.toDouble() * s
    }
    return sqrt(sum / sampleCount).toFloat()
}

