private fun offer(work: Work) {
    if (queue.offer(work)) return
    var dropped = queue.poll()
    if (dropped is Work.GapReset) {
        // sentinel 是唯一一次 gap-reset 的载体，丢了该静默段永不 reset（假命中）；
        // 全队列同时至多一个 sentinel（armed 才入队，重新 arm 需先喂过音频），可安全回插
        queue.offer(dropped)
        dropped = queue.poll()
    }
    queue.offer(work)
}

