/** 取命中位置附近的窗口片段，保证搜索词出现在摘要中。 */
private fun windowAround(text: String, query: String): String {
    val t = text.replace(WHITESPACE, " ").trim()
    val idx = t.indexOf(query, ignoreCase = true)
    if (idx < 0) return truncate(t)
    val start = maxOf(0, idx - SNIPPET_MAX_CHARS / 2)
    val end = minOf(t.length, start + SNIPPET_MAX_CHARS)
    return (if (start > 0) "…" else "") + t.substring(start, end) + (if (end < t.length) "…" else "")
}

private fun truncate(text: String): String =
    text.replace(WHITESPACE, " ").trim().let { t ->
        if (t.length > SNIPPET_MAX_CHARS) t.take(SNIPPET_MAX_CHARS) + "…" else t
    }

