@Volatile private var lastActive: VoiceSessionManager.BubbleSink? = null

private fun active(): VoiceSessionManager.BubbleSink {
    val target = if (carrier() == ReplyCarrier.FULLSCREEN) fullscreen else overlay
    if (target !== lastActive) {
        lastActive?.hide()
        lastActive = target
    }
    return target
}

override fun hideLater(delayMs: Long) {
